{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "definitions": {},
    "id": "https://github.com/landrews33/asteriskmqtt/config.json",
    "properties": {
        "asterisk": {
            "id": "/properties/asterisk",
            "properties": {
                "host": {
                    "id": "/properties/asterisk/properties/host",
                    "type": "string"
                },
                "password": {
                    "id": "/properties/asterisk/properties/password",
                    "type": "string"
                },
                "port": {
                    "id": "/properties/asterisk/properties/port",
                    "type": "string"
                },
                "singleeventpercall": {
                    "id": "/properties/asterisk/properties/singleeventpercall",
                    "type": "boolean"
                },
                "user": {
                    "id": "/properties/asterisk/properties/user",
                    "type": "string"
                }
            },
            "required": [
                "host",
                "password",
                "port",
                "singleeventpercall",
                "user"
            ],
            "type": "object"
        },
        "lines": {
            "id": "/properties/lines",
            "items": {
                "id": "/properties/lines/items",
                "properties": {
                    "channel": {
                        "id": "/properties/lines/items/properties/channel",
                        "type": "string"
                    },
                    "dids": {
                        "id": "/properties/lines/items/properties/dids",
                        "items": {
                            "id": "/properties/lines/items/properties/dids/items",
                            "properties": {
                                "candial": {
                                    "id": "/properties/lines/items/properties/dids/items/properties/candial",
                                    "type": "boolean"
                                },
                                "command_topic": {
                                    "id": "/properties/lines/items/properties/dids/items/properties/command_topic",
                                    "type": "string"
                                },
                                "did": {
                                    "id": "/properties/lines/items/properties/dids/items/properties/did",
                                    "type": "string"
                                },
                                "id": {
                                    "id": "/properties/lines/items/properties/dids/items/properties/id",
                                    "type": "string"
                                },
                                "status_topic": {
                                    "id": "/properties/lines/items/properties/dids/items/properties/status_topic",
                                    "type": "string"
                                }
                            },
                            "required": [
                                "did",
                                "command_topic",
                                "status_topic",
                                "candial",
                                "id"
                            ],
                            "type": "object"
                        },
                        "type": "array"
                    },
                    "internal": {
                        "id": "/properties/lines/items/properties/internal",
                        "type": "boolean"
                    }
                },
                "required": [
                    "internal",
                    "dids",
                    "channel"
                ],
                "type": "object"
            },
            "type": "array"
        },
        "mqtt": {
            "id": "/properties/mqtt",
            "properties": {
                "password": {
                    "id": "/properties/mqtt/properties/password",
                    "type": "string"
                },
                "url": {
                    "id": "/properties/mqtt/properties/url",
                    "type": "string"
                },
                "username": {
                    "id": "/properties/mqtt/properties/username",
                    "type": "string"
                }
            },
            "required": [
                "url",
                "username",
                "password"
            ],
            "type": "object"
        }
    },
    "required": [
        "lines",
        "mqtt",
        "asterisk"
    ],
    "type": "object"
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "additionalProperties": false,
    "definitions": {
        "mntent": {
            "additionalItems": false,
            "description": "An fstab entry",
            "properties": {
                "device": {
                    "type": "string"
                },
                "dump": {
                    "minimum": 0,
                    "type": "integer"
                },
                "fsck": {
                    "minimum": 0,
                    "type": "integer"
                },
                "fstype": {
                    "type": "string"
                },
                "options": {
                    "items": {
                        "type": "string"
                    },
                    "minItems": 1,
                    "type": "array"
                }
            },
            "required": [
                "device",
                "fstype"
            ],
            "title": "mntent",
            "type": "object"
        }
    },
    "description": "JSON representation of /etc/fstab",
    "patternProperties": {
        "^/([^/]+(/[^/]+)*)?$": {
            "$ref": "#/definitions/mntent"
        }
    },
    "properties": {
        "swap": {
            "$ref": "#/definitions/mntent"
        }
    },
    "required": [
        "/",
        "swap"
    ],
    "title": "/etc/fstab",
    "type": "object"
}

