{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "RetryExam test options",
    "description": "Options for a RetryExam test.",
    "type": "object",
    "additionalProperties": false,
    "properties": {
        "questionGroups": {
            "description": "Array of QID difficulty groups, one per difficulty level of questions.",
            "type": "array",
            "items": {
                "description": "Array of QID topic groups, one per topic of questions.",
                "type": "array",
                "items": {
                    "description": "Array of question IDs (QIDs) for this topic and difficulty.",
                    "type": "array",
                    "item": {
                        "description": "A single test question.",
                        "type": "object",
                        "additionalProperties": false,
                        "properties": {
                            "qid": {
                                "$ref": "#/definitions/questionQID"
                            },
                            "points": {
                                "$ref": "#/definitions/questionPoints"
                            }
                        },
                        "required": [
                            "qid",
                            "points"
                        ]
                    }
                }
            }
        },
        "zones": {
            "description": "Array of \"zones\" in the test, each containing questions that can be randomized within the zone.",
            "type": "array",
            "items": {
                "$ref": "#/definitions/zone"
            }
        },
        "unlimitedVariants": {
            "description": "Whether to generate new variants for all students, rather than using a limited set.",
            "type": "boolean",
            "default": false
        },
        "variantsPerQuestion": {
            "description": "Number of variants to select from per question.",
            "type": "integer",
            "minimum": 1,
            "default": 3
        },
        "availDate": {
            "description": "The date after which the test is available for students to view.",
            "type": "string"
        },
        "nQuestions": {
            "description": "The number of questions to select for each instance of this test.",
            "type": "integer"
        },
        "timeLimitMin": {
            "description": "The number of minutes allowed for this test.",
            "type": "integer"
        },
        "text": {
            "description": "HTML text shown on the test overview page.",
            "type": "string"
        }
    },
    "oneOf": [
        {
            "type": "object",
            "required": [
                "questionGroups",
                "nQuestions"
            ]
        },
        {
            "type": "object",
            "required": [
                "zones"
            ],
            "not": {
                "type": "object",
                "required": [
                    "nQuestions"
                ]
            }
        }
    ],
    "definitions": {
        "zone": {
            "type": "object",
            "properties": {
                "title": {
                    "description": "Zone title, displayed to the students at the top of the question list for the zone.",
                    "type": "string"
                },
                "questions": {
                    "description": "Array of questions in the zone.",
                    "type": "array",
                    "minItems": 1,
                    "items": {
                        "$ref": "#/definitions/question"
                    }
                }
            },
            "required": [
                "questions"
            ]
        },
        "question": {
            "type": "object",
            "properties": {
                "points": {
                    "$ref": "#/definitions/questionPoints"
                },
                "qid": {
                    "$ref": "#/definitions/questionQID"
                },
                "qids": {
                    "description": "Array of possible qids for a question.",
                    "type": "array",
                    "minItems": 1,
                    "items": {
                        "$ref": "#/definitions/questionQID"
                    }
                }
            },
            "required": [
                "points"
            ],
            "oneOf": [
                {
                    "type": "object",
                    "required": [
                        "qid"
                    ]
                },
                {
                    "type": "object",
                    "required": [
                        "qids"
                    ]
                }
            ]
        },
        "questionPoints": {
            "description": "An array of points values.",
            "type": "array",
            "minItems": 1,
            "items": {
                "type": "integer"
            }
        },
        "questionQID": {
            "description": "Question ID.",
            "type": "string"
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "O3D3xx Distance model configuration",
    "type": "object",
    "properties": {
        "Name": {
            "type": "string"
        },
        "PrivateType": {
            "type": "string",
            "default": "Distance",
            "attributes": [
                "private",
                "noexport"
            ]
        },
        "Type": {
            "type": "string",
            "enum": [
                "Distance"
            ],
            "attributes": [
                "readonly"
            ]
        },
        "ROIs": {
            "type": "string"
        },
        "SwitchPoint1": {
            "type": "number"
        },
        "SwitchPoint2": {
            "type": "number"
        },
        "ValueOfBenefit": {
            "type": "integer",
            "minimum": 0,
            "maximum": 2,
            "default": 0
        },
        "UseAnchorTracking": {
            "type": "boolean",
            "default": false
        },
        "HasAnchorTeachData": {
            "type": "boolean",
            "attributes": [
                "readonly"
            ]
        },
        "AnchorData": {
            "type": "string",
            "attributes": [
                "private",
                "noexport"
            ]
        }
    },
    "required": [
        "Name",
        "Type",
        "ROIs",
        "SwitchPoint1",
        "SwitchPoint2",
        "ValueOfBenefit"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "title": "WDS Schema",
    "description": "Definition of WDS web services.",
    "definitions": {
        "datasource": {
            "type": "string",
            "title": "Datasource",
            "description": "FAOSTAT datasource.",
            "default": "faostatdb",
            "enum": [
                "faostat",
                "faostatdb",
                "faostatglbl",
                "faostatprod",
                "faostatproddiss"
            ]
        },
        "lang_faostat": {
            "type": "string",
            "title": "Language",
            "description": "Language of the output.",
            "default": "E",
            "enum": [
                "E",
                "F",
                "S",
                "A",
                "C",
                "R"
            ]
        }
    },
    "properties": {
        "groupsanddomains": {
            "type": "object",
            "title": "Groups and Domains",
            "description": "List of FAOSTAT groups and domains",
            "method": "GET",
            "properties": {
                "schema": {
                    "type": "object",
                    "title": "Input schema",
                    "description": "Description of the input parameters.",
                    "properties": {
                        "method": {
                            "default": "GET"
                        },
                        "endpoint": {
                            "default": "/groupsanddomains"
                        },
                        "datasource": {
                            "$ref": "#/definitions/datasource"
                        },
                        "lang_faostat": {
                            "$ref": "#/definitions/lang_faostat"
                        }
                    }
                }
            }
        },
        "bulkdownloads": {
            "type": "object",
            "title": "Bulk Downloads",
            "description": "List of FAOSTAT bulk downloads.",
            "method": "GET",
            "properties": {
                "schema": {
                    "type": "object",
                    "title": "Input schema",
                    "description": "Description of the input parameters.",
                    "properties": {
                        "method": {
                            "default": "GET"
                        },
                        "datasource": {
                            "$ref": "#/definitions/datasource"
                        },
                        "domain": {
                            "type": "string",
                            "title": "Domain Code",
                            "description": "FAOSTAT Domain Code."
                        },
                        "lang_faostat": {
                            "$ref": "#/definitions/lang_faostat"
                        }
                    }
                }
            }
        },
        "procedures/usp_GetListBox": {
            "type": "object",
            "title": "Bulk Downloads",
            "description": "List of FAOSTAT bulk downloads.",
            "method": "GET",
            "properties": {
                "datasource": {
                    "$ref": "#/definitions/datasource"
                },
                "domain": {
                    "type": "string",
                    "title": "Domain Code",
                    "description": "FAOSTAT Domain Code."
                },
                "tab_group": {
                    "type": "integer",
                    "title": "Tab Group",
                    "description": "Tab group as displayed in FAOSTAT Download."
                },
                "tab_index": {
                    "type": "integer",
                    "title": "Tab Index",
                    "description": "Tab index within the group."
                },
                "lang_faostat": {
                    "$ref": "#/definitions/lang_faostat"
                }
            }
        }
    }
}

