{
    "additionalProperties": false,
    "definitions": {
        "i18n": {
            "additionalProperties": false,
            "properties": {
                "locales": {
                    "additionalProperties": false,
                    "patternProperties": {
                        "^[a-zA-Z]{2,3}(-[a-zA-Z]{4})?(-([a-zA-Z]{2}|[0-9]{3}))?(-[a-zA-Z]{5,8})?(-x(-[a-zA-Z0-9]{1,8})+)?$": {
                            "oneOf": [
                                {
                                    "description": "Localization file to use for i18n",
                                    "type": "string"
                                },
                                {
                                    "additionalProperties": false,
                                    "description": "Localization options to use for the locale",
                                    "properties": {
                                        "baseHref": {
                                            "description": "HTML base HREF to use for the locale (defaults to the locale code)",
                                            "type": "string"
                                        },
                                        "translation": {
                                            "description": "Localization file to use for i18n",
                                            "type": "string"
                                        }
                                    },
                                    "type": "object"
                                }
                            ]
                        }
                    },
                    "type": "object"
                },
                "sourceLocale": {
                    "oneOf": [
                        {
                            "default": "en-US",
                            "description": "Specifies the source locale of the application.",
                            "pattern": "^[a-zA-Z]{2,3}(-[a-zA-Z]{4})?(-([a-zA-Z]{2}|[0-9]{3}))?(-[a-zA-Z]{5,8})?(-x(-[a-zA-Z0-9]{1,8})+)?$",
                            "type": "string"
                        },
                        {
                            "additionalProperties": false,
                            "description": "Localization options to use for the source locale",
                            "properties": {
                                "baseHref": {
                                    "description": "HTML base HREF to use for the locale (defaults to the locale code)",
                                    "type": "string"
                                },
                                "code": {
                                    "description": "Specifies the locale code of the source locale",
                                    "pattern": "^[a-zA-Z]{2,3}(-[a-zA-Z]{4})?(-([a-zA-Z]{2}|[0-9]{3}))?(-[a-zA-Z]{5,8})?(-x(-[a-zA-Z0-9]{1,8})+)?$",
                                    "type": "string"
                                }
                            },
                            "type": "object"
                        }
                    ]
                }
            },
            "type": "object"
        },
        "project": {
            "additionalProperties": false,
            "description": "Project options.",
            "if": {
                "properties": {
                    "projectType": {
                        "const": "library"
                    }
                }
            },
            "properties": {
                "architect": {
                    "$ref": "#/definitions/tool",
                    "default": {}
                },
                "cli": {
                    "$ref": "#/definitions/tool",
                    "default": {}
                },
                "i18n": {
                    "$ref": "#/definitions/i18n",
                    "default": {}
                },
                "prefix": {
                    "description": "The prefix to apply to generated selectors.",
                    "type": "string"
                },
                "projectType": {
                    "description": "Project type.",
                    "enum": [
                        "application",
                        "library"
                    ],
                    "type": "string"
                },
                "root": {
                    "description": "Root of the project sourcefiles.",
                    "type": "string"
                },
                "schematics": {
                    "$ref": "#/definitions/tool",
                    "default": {}
                },
                "sourceRoot": {
                    "description": "The root of the source files, assets and index.html file structure.",
                    "type": "string"
                },
                "targets": {
                    "$ref": "#/definitions/tool",
                    "default": {}
                }
            },
            "required": [
                "root",
                "projectType"
            ],
            "then": {
                "not": {
                    "required": [
                        "i18n"
                    ]
                }
            },
            "type": "object"
        },
        "tool": {
            "additionalProperties": true,
            "description": "Tool options.",
            "properties": {
                "$schema": {
                    "description": "Link to schema.",
                    "type": "string"
                }
            },
            "type": "object"
        }
    },
    "properties": {
        "$schema": {
            "description": "Link to schema.",
            "type": "string"
        },
        "architect": {
            "$ref": "#/definitions/tool",
            "default": {}
        },
        "cli": {
            "$ref": "#/definitions/tool",
            "default": {}
        },
        "defaultProject": {
            "description": "The default project.",
            "type": "string"
        },
        "newProjectRoot": {
            "default": "./",
            "description": "New project root.",
            "type": "string"
        },
        "projects": {
            "additionalProperties": {
                "$ref": "#/definitions/project"
            },
            "default": {},
            "description": "A map of project names to project options.",
            "type": "object"
        },
        "schematics": {
            "$ref": "#/definitions/tool",
            "default": {}
        },
        "targets": {
            "$ref": "#/definitions/tool",
            "default": {}
        },
        "version": {
            "description": "Workspace Schema version.",
            "type": "number"
        }
    },
    "required": [
        "version"
    ],
    "title": "Angular Devkit Workspace Schema for validating workspace JSON.",
    "type": "object"
}

{
    "description": "Creates a new generic NgModule definition in the given or default project.",
    "properties": {
        "commonModule": {
            "default": true,
            "description": "When true, the new NgModule imports \"CommonModule\". ",
            "type": "boolean",
            "visible": false
        },
        "flat": {
            "default": false,
            "description": "When true, creates the new files at the top level of the current project root. ",
            "type": "boolean"
        },
        "lintFix": {
            "default": false,
            "description": "When true, applies lint fixes after generating the module.",
            "type": "boolean",
            "x-user-analytics": 15
        },
        "module": {
            "alias": "m",
            "description": "The declaring NgModule.",
            "type": "string"
        },
        "name": {
            "$default": {
                "$source": "argv",
                "index": 0
            },
            "description": "The name of the NgModule.",
            "type": "string",
            "x-prompt": "What name would you like to use for the NgModule?"
        },
        "path": {
            "description": "The path at which to create the NgModule, relative to the workspace root.",
            "format": "path",
            "type": "string",
            "visible": false
        },
        "project": {
            "$default": {
                "$source": "projectName"
            },
            "description": "The name of the project.",
            "type": "string"
        },
        "route": {
            "description": "The route path for a lazy-loaded module. When supplied, creates a component in the new module, and adds the route to that component in the `Routes` array declared in the module provided in the `--module` option.",
            "type": "string"
        },
        "routing": {
            "default": false,
            "description": "When true, creates a routing module.",
            "type": "boolean",
            "x-user-analytics": 17
        },
        "routingScope": {
            "default": "Child",
            "description": "The scope for the new routing module.",
            "enum": [
                "Child",
                "Root"
            ],
            "type": "string"
        }
    },
    "required": [
        "name"
    ],
    "title": "Angular Module Options Schema",
    "type": "object"
}

{
    "properties": {
        "all": {
            "default": false,
            "description": "When true, update all packages in `package.json`.",
            "type": "boolean"
        },
        "force": {
            "default": false,
            "description": "When false (the default), reports an error if installed packages are incompatible with the update.",
            "type": "boolean"
        },
        "from": {
            "description": "When using `--migrateOnly` for a single package, the version of that package from which to migrate.",
            "type": "string"
